<script setup lang="ts">
import { useDemoStore } from '~/stores/demo'
import { useSessionStore } from '~/stores/session'
definePageMeta({layout:'workspace'});import{selectReport,selectReportVideos}from'~/demo/selectors.mjs';const route=useRoute(),demo=useDemoStore(),session=useSessionStore();const report=computed(()=>selectReport(demo.data,session.session||{},String(route.params.id)));const videos=computed(()=>selectReportVideos(demo.data,report.value));const busy=ref(false),error=ref('');const total=computed(()=>videos.value.reduce((a:any,v:any)=>({views:a.views+v.views,likes:a.likes+v.likes,comments:a.comments+v.comments}),{views:0,likes:0,comments:0}));async function generate(){busy.value=true;error.value='';try{const res:any=await $fetch('/api/ai/report-insight',{method:'POST',body:{reportId:report.value.id,reportType:report.value.type,name:report.value.name,videoIds:report.value.videoIds}});demo.run({type:'report:save-insight',reportId:report.value.id,insight:res.insight,mode:res.mode},session.session||{})}catch(e:any){error.value=e?.data?.statusMessage||'Could not create the insight. Try again.'}finally{busy.value=false}}</script>
<template><div v-if="report" class="page-content"><div class="page-title-row"><div><NuxtLink class="flow-link" to="/app/creator-suites">← Creator Suites</NuxtLink><span class="page-label">YOUTUBE BRAND DEAL REPORT</span><h1>{{report.name}}</h1><p>{{report.brandName}} · Public video snapshot</p></div><button class="button button-primary" :disabled="busy" @click="generate">{{busy?'Generating…':'✦ Generate Executive Insight'}}</button></div><div class="metric-grid"><div class="metric-panel"><span class="metric-label">Public views</span><strong class="metric-value">{{total.views.toLocaleString()}}</strong><span class="metric-note">Cumulative video counter</span></div><div class="metric-panel"><span class="metric-label">Likes</span><strong class="metric-value">{{total.likes.toLocaleString()}}</strong><span class="metric-note">Public video counter</span></div><div class="metric-panel"><span class="metric-label">Comments</span><strong class="metric-value">{{total.comments.toLocaleString()}}</strong><span class="metric-note">Public video counter</span></div><div class="metric-panel"><span class="metric-label">Selected videos</span><strong class="metric-value">{{videos.length}}</strong><span class="metric-note">Fixture report evidence</span></div></div><p v-if="error" class="form-hint" role="alert">{{error}}</p><section class="panel"><div class="panel-head"><div><h2>Selected video evidence</h2><p>All statistics shown are sample public counters</p></div><span class="tag tag-muted">DEMO DATA</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Video</th><th>Published</th><th>Views</th><th>Likes</th><th>Comments</th></tr></thead><tbody><tr v-for="video in videos" :key="video.id"><td>{{video.title}}</td><td>{{video.publishedAt}}</td><td>{{video.views.toLocaleString()}}</td><td>{{video.likes.toLocaleString()}}</td><td>{{video.comments.toLocaleString()}}</td></tr></tbody></table></div></section><section v-if="report.insight" class="insight-panel"><div class="insight-heading"><strong><span class="gemini-mark">✦</span> Executive Insight</strong><span class="tag" :class="report.insight.mode==='gemini'?'tag-violet':'tag-amber'">{{report.insight.mode==='gemini'?'Generated with Gemini':'Sample insight'}}</span></div><div class="insight-body"><div><p>{{report.insight.summary}}</p><h3>Strengths</h3><ul class="insight-list"><li v-for="x in report.insight.strengths" :key="x">{{x}}</li></ul></div><div><h3>Recommendations</h3><ul class="insight-list"><li v-for="x in report.insight.recommendations" :key="x">{{x}}</li></ul><h3 style="margin-top:14px">Limitations</h3><ul class="insight-list"><li v-for="x in report.insight.limitations" :key="x">{{x}}</li></ul></div></div></section><p class="form-hint">Public counters are cumulative. They are not campaign-period views, private YouTube Analytics or evidence of sales.</p></div><div v-else class="page-content"><div class="empty-state">Report not found or outside this role's access.</div></div></template>
